if (root == nullptr) {
    root = new TreeNode<int>(item);
} else {
    if (item < root->data) {
        avlInsert(root->left, item);
        if (bstHeight(root->left) - bstHeight(root->right) == 2) {
            if (item < root->left->data) {
                root = avlRotateRight(root);
            } else {
                root = avlRotateLeft(root->left);
                root = avlRotateRight(root);
            }
        }
    } else if (item > root->data) {
        avlInsert(root->right, item);
        if (bstHeight(root->right) - bstHeight(root->left) == 2) {
            if (item > root->right->data) {
                root = avlRotateLeft(root);
            } else {
                root = avlRotateRight(root->right);
                root = avlRotateLeft(root);
            }
        }
    }
}

